/* ---------- Glisser pour trier les suggestions ---------- */
/* Vers la droite : Analyser ; vers la gauche : Écarter (tout de suite, « Annuler » pendant 6 secondes).
   Même geste que pour changer le statut d'une candidature ; un toucher simple garde son effet normal. */
function sgSwipeAll(L){L.querySelectorAll("article.sgc").forEach(function(art){if(art.parentNode.classList.contains("sgsw"))return;var w=document.createElement("div");w.className="sgsw";art.parentNode.insertBefore(w,art);w.appendChild(art);sgSwipe(w,art)})}
function sgSwipe(w,art){var x0=0,y0=0,dx=0,on=false,dec=false,pid=null,bg=null,moved=0;
art.addEventListener("pointerdown",function(e){if(e.pointerType==="mouse"&&e.button!==0)return;if(e.target.closest("input,select,textarea,.sgwhy"))return;x0=e.clientX;y0=e.clientY;dx=0;on=true;dec=false;pid=e.pointerId});
art.addEventListener("pointermove",function(e){if(!on||e.pointerId!==pid)return;var mx=e.clientX-x0,my=e.clientY-y0;if(!dec){if(Math.abs(mx)>14&&Math.abs(mx)>Math.abs(my)*1.4){dec=true;try{art.setPointerCapture(pid)}catch(er){}if(!bg){bg=document.createElement("div");bg.className="swbg";w.insertBefore(bg,w.firstChild)}w.classList.add("swing")}else if(Math.abs(my)>10){on=false;return}else return}
dx=Math.max(-170,Math.min(170,mx));art.style.transform="translateX("+dx+"px)";bg.className="swbg "+(dx>0?"r":"l")+(Math.abs(dx)>=90?" go":"");bg.innerHTML=dx>0?'<span>Analyser →</span>':'<span>← Écarter</span>';e.preventDefault()});
function end(){if(!on)return;on=false;if(!dec)return;moved=Date.now();var v=dx;art.style.transition="transform .18s";art.style.transform="";setTimeout(function(){art.style.transition="";w.classList.remove("swing");if(bg){bg.remove();bg=null}},190);
if(v>=90){setTimeout(function(){var b=art.querySelector('[data-a="an"]');if(b)b.click()},200)}else if(v<=-90){setTimeout(function(){var b=art.querySelector('[data-a="hide"]');if(b){b.dataset.ok="1";b.click()}},200)}}
art.addEventListener("pointerup",end);art.addEventListener("pointercancel",end);
/* Un glissement ne doit pas compter comme un toucher sur le bouton où le doigt s'est posé. */
art.addEventListener("click",function(e){if(e.isTrusted&&Date.now()-moved<350){e.preventDefault();e.stopPropagation()}},true)}
